#include <stdio.h>

int find(const char *text, const char *pattern) {
    for (int i = 0; text[i] != '\0'; i++) {
        int j = 0;
        while (pattern[j] != '\0' && text[i + j] == pattern[j]) {
            j++;
        }
        if (pattern[j] == '\0') {
            return i;
        }
    }
    return -1;
}

int main() {
    printf("%d\n", find("abcabd", "abd"));
    return 0;
}
